"""Per-repository template for tools/build_notebook.py (NOTEBOOK_SPEC 2.5 §4 standalone carrier).

Only the task-specific prose and stage cells live here. Runtime install, the embedded pipeline
modules (pipeline.py, samples.py, metrics.py), and the model pin/stage/verify cells are produced by
the generator from repository sources so they cannot drift from the package.

This template configures an E2E continued-pre-training workflow: the pinned BERT-Base uncased snapshot is
digest-verified and loaded, a digest-pinned real corpus (SciTLDR paper abstracts) is fetched, validated and
split, both inference contracts are exercised, the frozen model's masked-token metrics on held-out abstracts
are read beside a unigram floor, a bounded masked-language-model fine-tuning of the last encoder layers adapts
the model to the domain in the kernel, the held-out split is scored again, and the adapter is exported and
reloaded.

Review fixes (Notebook Review Framework v1, review PR #8, MLM-M1..M4 / MLM-m1..m5): the runtime is the fleet's uv
isolated environment (no in-kernel install, no restart), every re-run of Sections 5-7 starts from the pretrained
model, BYOD limits are checked in Section 4 before any model call, and the guided layer (how to use, roadmap,
predictions, worked answers, a change-one-thing activity, troubleshooting, glossary, conclusion) is added.

Review fixes (tutorial triage 2026-10-15, row 5, T5-1..T5-8; owner rulings 2026-10-17): TRAINABLE_LAYERS and
LEARNING_RATE are re-selected on validation by the grid pre-registered in docs/reselection-preregistration-2026-10-17.md,
the held-out result is a fresh 100-abstract test drawn from the never-scored SciTLDR dev remainder and scored only under the pre-registered settings,
the old test is reported, labelled, as the exposed development test, the pretraining-overlap limitation is stated (DAT9),
BYOD refusals are one message that invalidates the run (DAT20), and the notebook declares NOTEBOOK_SPEC 2.5, its kind
and the DOC17 use notice.
"""
# ruff: noqa: E501  -- markdown prose and code-cell text are kept on single lines for readable rendering

_SKIP_WHEN_REFUSED = (
    "if RUN_STATE['refused']:\n"
    "    print({{'skipped': 'Section 4 refused the BYOD input, so this cell does not run on stale data', 'reason': RUN_STATE['refused'], 'what_to_do': 'fix the file, then select Section 4 and choose Runtime -> Run after'}})\n"
    "else:\n"
)


def _guarded(code: str) -> str:
    """DAT20: a cell after Section 4 runs only while Section 4's input is accepted.

    Form fields (and the imports above them) stay at top level so the form still renders; the rest of the cell
    moves under `else:`, so a refused BYOD input leaves the later cells printing `skipped`, not stale results."""
    lines = code.split("\n")
    params = [i for i, line in enumerate(lines) if "# @param" in line]
    head, body = (lines[: params[-1] + 1], lines[params[-1] + 1 :]) if params else ([], lines)
    while body and not body[0].strip():
        body.pop(0)
    indented = ["    " + line if line.strip() else line for line in body]
    return ("\n".join(head) + "\n\n" if head else "") + _SKIP_WHEN_REFUSED + "\n".join(indented)


